using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    """
    You are a research agent. Your job is to research a topic by:
    1. Searching the web for relevant information using the search tool.
    2. Taking notes on key findings using the note-taking tool.
    3. Once you have gathered enough information, produce a concise summary.

    Always search multiple queries to get broad coverage. Take notes on the
    most important findings before writing the final summary.
    """)
{
    Tools = [.. AIFunctionFactory.Create(tools)]
};

Console.WriteLine("Research Agent Ready!");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Notes Collected ---");
foreach (var note in tools.GetNotes())
{
    Console.WriteLine($"• {note}");
}

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
    public IReadOnlyList<string> SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        Console.WriteLine($"  [🔍 Searching: \"{query}\"]");

        // Simulated web search results for demonstration purposes.
        // Replace with a real search API (e.g., Bing Search, Google Custom Search).
        return
        [
            $"Result 1 for '{query}': According to recent studies, this topic has seen significant developments in 2025-2026.",
            $"Result 2 for '{query}': Experts suggest that key trends include increased adoption and new frameworks.",
            $"Result 3 for '{query}': A comprehensive review published in 2026 highlights challenges and opportunities.",
        ];
    }

    [Description("Save a note capturing a key finding from research. Use this to record important facts before writing the summary.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [📝 Note saved: \"{note[..Math.Min(note.Length, 60)]}...\"]");
        return $"Note saved successfully. Total notes: {_notes.Count}";
    }

    public IReadOnlyList<string> GetNotes() => _notes.AsReadOnly();
}

